INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3201, 'Leviticus 20:2', 'Leviticus', 20, 2, '&nbsp;”اِسرائيلو ته ووايه، کۀ ستاسو يو خپل کس يا يو مسافر چې ستاسو سره اوسيږى هغه د خپلو ماشومانو نه يو ماشوم مولک بُت ته پېش کړى نو ټول قوم به هغه سنګسار کړى او مړ به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3202, 'Leviticus 20:3', 'Leviticus', 20, 3, '&nbsp;کۀ څوک د خپلو ماشومانو نه يو ماشوم مولک بُت ته ورکړى او زما مقدسه خېمه ناپاکه کړى او زما د مقدس نوم سپکاوے وکړى، نو زۀ به ترې نه مخ واړوم او هغه به نور زما د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3203, 'Leviticus 20:4', 'Leviticus', 20, 4, '&nbsp;خو کۀ قوم په هغه کس باندې ځان ناجاڼه کړى چې څۀ يې کړى وى او هغه ونۀ وژنى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3204, 'Leviticus 20:5', 'Leviticus', 20, 5, '&nbsp;نو زۀ به په خپله د هغه کس نه، د هغۀ د ټولې خاندان نه او د هغه ټولو نه مخ واړوم چې زما نافرمانى وکړى او د مولک بُت عبادت وکړى. زۀ به هغوئ نور خپل خلق نه ګڼم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3205, 'Leviticus 20:6', 'Leviticus', 20, 6, '&nbsp;کۀ څوک د هغه خلقو نصيحت اورېدلو له ورځى چې د مړو د روحونو مشورې ورکوى، نو زۀ به د هغۀ نه مخ واړوم او زۀ به هغه نور د خپلو خلقو نه نۀ ګڼم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3206, 'Leviticus 20:7', 'Leviticus', 20, 7, '&nbsp;خپل ځانونه وقف کړئ او مقدس اوسئ، ځکه چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3207, 'Leviticus 20:8', 'Leviticus', 20, 8, '&nbsp;زما قانون ومنئ، ځکه چې زۀ مالِک خُدائ يم او تاسو مقدس کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3208, 'Leviticus 20:9', 'Leviticus', 20, 9, '&nbsp;مالِک خُدائ دا اصُول وښودل. کۀ څوک خپل مور يا پلار ته ښېرې وکړى نو هغه به وژلے شى، او خُون به يې په خپله غاړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3209, 'Leviticus 20:10', 'Leviticus', 20, 10, '&nbsp;کۀ يو سړے د بل سړى د ښځې سره زنا وکړى نو دوئ دواړه به وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3210, 'Leviticus 20:11', 'Leviticus', 20, 11, '&nbsp;کۀ يو سړے د پلار د ښځې سره څملى او د پلار سپکاوے وکړى، نو هغه سړے او ښځه دواړه به وژلے شى. د هغوئ خُون په خپله غاړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3211, 'Leviticus 20:12', 'Leviticus', 20, 12, '&nbsp;کۀ يو سړے د خپلې اِنږور سره څملى، نو هغوئ دواړه دې ووژلے شى. هغوئ ډېر غلط کار کړے دے او خُون يې په خپله غاړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3212, 'Leviticus 20:13', 'Leviticus', 20, 13, '&nbsp;کۀ يو سړے د بل سړى سره جنسى تعلقات وساتى، هغوئ يو شرمناک کار کړے دے او دواړه به ووژلے شى. د هغوئ خُون په خپله غاړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3213, 'Leviticus 20:14', 'Leviticus', 20, 14, '&nbsp;کۀ يو سړے يوه ښځه او د هغې مور وادۀ کړى، نو هغوئ درې واړه به په اور کښې سوزولے شى ځکه چې هغوئ ډېر بد عمل کړے دے، ستاسو په مينځ کښې به د داسې کار اجازت نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3214, 'Leviticus 20:15', 'Leviticus', 20, 15, '&nbsp;کۀ يو سړے د ځناور سره زنا وکړى، نو هغه سړے او ځناور به وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3215, 'Leviticus 20:16', 'Leviticus', 20, 16, '&nbsp;کۀ يوه ښځه د ځناور سره د غلط کار کولو کوشش وکړى، نو هغه او ځناور به ووژلے شى. د هغوئ خُون په خپله غاړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3216, 'Leviticus 20:17', 'Leviticus', 20, 17, '&nbsp;کۀ يو سړے د خپلې سکه يا ناسکه خور سره وادۀ وکړى او هغوئ د يو بل سپکاوے وکړى، نو دا يو د بې‌شرمۍ کار دے او هغوئ دې د خپلو خلقو نه وشړلے شى، هغۀ د خپلې خور سپکاوے کړے دے او هغوئ ته دې د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3217, 'Leviticus 20:18', 'Leviticus', 20, 18, '&nbsp;کۀ يو سړے د يوې ښځې سره د هغې د مياشتنۍ بيمارۍ په دوران کښې څملى، نو هغوئ دواړه به د قوم نه شړلے شى، ځکه چې هغوئ د پاکوالى په حقله اصُول مات کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3218, 'Leviticus 20:19', 'Leviticus', 20, 19, '&nbsp;کۀ يو سړے د خپلې مور خور سره يا د پلار خور سره څملى، نو هغوئ ته دې خامخا د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3219, 'Leviticus 20:20', 'Leviticus', 20, 20, '&nbsp;کۀ يو سړے د خپلې ترۀ ښځې سره څملى، نو هغه د خپل ترۀ سپکاوے کوى، نو ذمه وارى به د هغوئ په خپله غاړه وى، او بې‌اولاده به مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3220, 'Leviticus 20:21', 'Leviticus', 20, 21, '&nbsp;کۀ يو سړے خپله ورنداره وادۀ کړى او ورور يې ژوندے وى، نو هغوئ به بې‌اولاده مړۀ شى. هغۀ يو ناپاکه کار کړے دے او هغۀ د خپل ورور سپکاوے کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3221, 'Leviticus 20:22', 'Leviticus', 20, 22, '&nbsp;مالِک خُدائ وفرمائيل، ”زما ټول قانون او حُکمونه ومنئ، نو داسې د کنعان مُلک نه به ونۀ شړلے شئ کوم مُلک له چې زۀ تاسو راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3222, 'Leviticus 20:23', 'Leviticus', 20, 23, '&nbsp;د هغه خلقو په رِواجونو پسې مۀ ځئ کوم چې هلته اوسيږى، هغه غېرقومونه به ترې نه وباسم نو تاسو به هغه مُلک ته ورننوځئ. زۀ د هغوئ د ټولو بدو عملونو په وجه د هغوئ نه کرکه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3223, 'Leviticus 20:24', 'Leviticus', 20, 24, '&nbsp;خو ما ستاسو سره وعده کړې ده چې هغه مُلک ستاسو خپل شى چې زرخېز او آباد وى او هغه به زۀ تاسو له درکړم. زۀ مالِک خُدائ ستاسو خُدائ پاک يم او ما تاسو د نورو قومونو نه جدا کړى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3224, 'Leviticus 20:25', 'Leviticus', 20, 25, '&nbsp;نو تاسو خامخا د حلالو او حرامو ځناورو او مارغانو په مينځ کښې فرق وکړئ. حرام ځناور او حرام مارغان مۀ خورئ. ما ورته ناپاک وئيلى دى او چې تاسو دا وخورئ نو ناپاک به شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3225, 'Leviticus 20:26', 'Leviticus', 20, 26, '&nbsp;تاسو به مقدس شئ او صِرف زما به شئ، ځکه چې زۀ مالِک خُدائ يم او زۀ مقدس يم. ما تاسو د نورو قومونو نه جدا کړى يئ چې تاسو صِرف زما اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3226, 'Leviticus 20:27', 'Leviticus', 20, 27, '&nbsp;هر يو سړے يا ښځه چې د مړو يا د پيريانو مشورې ورکوى هغه دې سنګسار کړے شى چې مړۀ شى، څوک چې دا کار کوى نو هغه به د خپل خُون ذمه وار وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3227, 'Leviticus 21:1', 'Leviticus', 21, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې د هارون د خاندان اِمامانو ته ووايه، ”کله چې د هغوئ يو خپلوان مړ شى نو د هغۀ په جنازه کښې شريکېدو په وجه به اِمام خپل ځان نۀ ناپاک کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3228, 'Leviticus 21:2', 'Leviticus', 21, 2, '&nbsp;خو د دې نه بغېر چې هغه يې نزدې خپلوان وى لکه مور، پلار، زوئ، لور، ورور،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3229, 'Leviticus 21:3', 'Leviticus', 21, 3, '&nbsp;يا پېغله خور چې د هغۀ په کور کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3230, 'Leviticus 21:4', 'Leviticus', 21, 4, '&nbsp;هغه دې د هغه چا په مرګ کښې خپل ځان ناپاک نۀ کړى چې د وادۀ په ذريعه د هغۀ خپلوان شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3231, 'Leviticus 21:5', 'Leviticus', 21, 5, '&nbsp;يو اِمام به هم د خپل سر يوه حِصه هم نۀ کلوى، نۀ به ږيره لنډوى او نۀ به خپل بدن غوڅوى چې دا ښکاره کړى چې غم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3232, 'Leviticus 21:6', 'Leviticus', 21, 6, '&nbsp;هغه به مقدس وى او چې زما نوم سپک نۀ کړى. هغه ما ته په اور باندې تيارېدونکې نذرانه پېش کوى، نو هغه دې خامخا مقدس وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3233, 'Leviticus 21:7', 'Leviticus', 21, 7, '&nbsp;يو اِمام به د کنجرې ښځې سره وادۀ نۀ کوى يا چې پېغله نۀ وى او يا طلاقه شوې وى ځکه چې هغه مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3234, 'Leviticus 21:8', 'Leviticus', 21, 8, '&nbsp;خلق به خامخا اِمام مقدس ګڼى، ځکه چې هغه ما ته په اور باندې تيارېدونکې نذرانه پېش کوى. زۀ مالِک خُدائ يم، زۀ مقدس يم او زۀ خپل خلق مقدس کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3235, 'Leviticus 21:9', 'Leviticus', 21, 9, '&nbsp;کۀ د يو اِمام لور کنجره شى، هغه د خپل پلار سپکاوے کوى، نو هغه به خامخا په اور کښې سوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3236, 'Leviticus 21:10', 'Leviticus', 21, 10, '&nbsp;د مشر اِمام په سر باندې د غوړولو تېل اچولے شوى دى او هغه پاک شوے دے چې د اِمامانو لِباس واغوندى، نو هغه به خپل وېښتۀ ببر نۀ پرېږدى نۀ به شلېدلې جامې اغوندى چې دا ښکاره کړى چې هغه غم ژړا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3237, 'Leviticus 21:13', 'Leviticus', 21, 13, '&nbsp;هغه به د يوې داسې جينۍ سره وادۀ کوى چې پاکه پېغله وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3238, 'Leviticus 21:14', 'Leviticus', 21, 14, '&nbsp;کونډه يا طلاقه شوې ښځه يا يوه کنجره ښځه به نۀ وادۀ کوى. هغه دې صِرف د يوې داسې جينۍ سره وادۀ کوى چې پاکه پېغله وى او هغه يې د خپلې قبيلې نه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3239, 'Leviticus 21:15', 'Leviticus', 21, 15, '&nbsp;ګنې، د هغۀ بچى به ناپاک وى، په کار دى چې هغوئ پاک وى. زۀ مالِک خُدائ يم او ما هغه د اِمام په توګه غوره کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3240, 'Leviticus 21:16', 'Leviticus', 21, 16, '&nbsp;مالِک خُدائ موسىٰ ته حُکم وکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3241, 'Leviticus 21:17', 'Leviticus', 21, 17, '&nbsp;”هارون ته ووايه، ستا د اولاد هغه يو کس به هم په اور تيارېدونکې نذرانه ما ته نۀ پېش کوى، کوم چې په بدن کښې څۀ عېب لرى. په دې خبرو به په راتلونکى ټولو وختونو کښې عمل کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3242, 'Leviticus 21:18', 'Leviticus', 21, 18, '&nbsp;داسې يو سړے هم دا نذرانه نۀ شى پېش کولے چې هغه په بدن کښې داسې عېب لرى لکه څوک چې ړوند، ګوډ، کوږ مخے يا معذُور وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3243, 'Leviticus 21:19', 'Leviticus', 21, 19, '&nbsp;څوک چې په لاس يا په پښه ګوډ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3244, 'Leviticus 21:20', 'Leviticus', 21, 20, '&nbsp;چې په ملا يې کُب وى يا مندرے وى، څوک چې د سترګو يا د څرمنې څۀ بيمارى لرى، او يا چې خصى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3245, 'Leviticus 21:21', 'Leviticus', 21, 21, '&nbsp;د هارون د اولاد داسې يو اِمام هم ما ته په اور تيارېدونکې نذرانه نۀ شى پېش کولے چې په بدن کښې څۀ عېب لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3246, 'Leviticus 21:22', 'Leviticus', 21, 22, '&nbsp;خو داسې کس په اور باندې تيارېدونکې نذرانه خوړلے شى چې ما ته پېش کيږى، يعنې هغه دواړه نذرانې په اور تيارېدونکې مقدسه نذرانه او په اور تيارېدونکې ډېره مقدسه نذرانه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3247, 'Leviticus 21:23', 'Leviticus', 21, 23, '&nbsp;خو ځکه چې هغه په بدن کښې څۀ عېب لرى، نو هغه دې مقدسې پړدې ته او قربان‌ګاه ته نزدې نۀ راځى. هغه دې دا مقدس ځايونه نۀ ناپاکه کوى، ځکه چې زۀ مالِک خُدائ يم او زۀ هغوئ مقدس کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3248, 'Leviticus 21:24', 'Leviticus', 21, 24, '&nbsp;نو دا هغه څۀ دى چې موسىٰ هارون ته، د هارون زامنو ته او ټولو بنى اِسرائيلو ته وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3249, 'Leviticus 22:1', 'Leviticus', 22, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3250, 'Leviticus 22:2', 'Leviticus', 22, 2, '&nbsp;”هارون او د هغۀ زامنو ته ووايه، تاسو زما د مقدس نوم سپکاوے مۀ کوئ، او د مقدسو نذرانو احترام کوئ کومې چې اِسرائيل ما ته وقف کوى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3251, 'Leviticus 22:3', 'Leviticus', 22, 3, '&nbsp;هغوئ ته ووايه چې کله ستاسو د اولاد يو کس ناپاک وى او مقدسو نذرانو ته نزدې راځى کومې چې اِسرائيلو ما ته وقف کړې وى، هغه دې بيا هيڅکله په قربان‌ګاه کښې خِدمت ونۀ کړى. په راتلونکى ټولو وختونو کښې به په دې عمل کوئ. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3252, 'Leviticus 22:4', 'Leviticus', 22, 4, '&nbsp;د هارون د اولاد يو کس هم دا مقدسې نذرانې نۀ شى خوړلے چې په هغۀ د جذام بيمارى وى يا د هغۀ د بدن نه څۀ وځى چې ترڅو پورې هغه پاک شوے نۀ وى. هر هغه اِمام ناپاک دے چې هغه داسې څۀ څيز له لاس وروړى چې هغه د يو مړى سره د لګېدو په وجه ناپاک وى يا د هغۀ د ذکر نه اوبۀ وځى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3253, 'Leviticus 22:5', 'Leviticus', 22, 5, '&nbsp;يا کۀ هغه يو ناپاک ځناور يا ناپاک کس له لاس وروړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3254, 'Leviticus 22:6', 'Leviticus', 22, 6, '&nbsp;هر يو اِمام چې ناپاک شى نو هغه به تر ماښامه پورې ناپاک وى، خو بيا به هم هغه مقدسې نذرانې نۀ شى خوړلے چې ترڅو پورې يې غسل نۀ وى کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3255, 'Leviticus 22:7', 'Leviticus', 22, 7, '&nbsp;چې کله نمر پرېوځى نو هغه پاک دے او بيا هغه مقدسې نذرانې خوړلے شى، کومې چې د هغۀ خوراک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3256, 'Leviticus 22:8', 'Leviticus', 22, 8, '&nbsp;هغه به د داسې ځناور غوښه نۀ خورى چې په خپل مرګ مړ وى يا ځنګلى ځناورو وژلے وى، په دې به هغه ناپاک شى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3257, 'Leviticus 22:9', 'Leviticus', 22, 9, '&nbsp;ټول اِمامان به هغه اصُول منى کوم چې ما ښودلى دى. ګنې، هغوئ به ګناهګار شى او مړۀ به شى، ځکه چې هغوئ مقدسو اصُولو ته سپک کتلى دى. زۀ مالِک خُدائ يم او زۀ هغوئ مقدس کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3258, 'Leviticus 22:10', 'Leviticus', 22, 10, '&nbsp;صِرف د اِمامانو د خاندان کس دا نذرانې خوړلے شى، بل څوک يې نۀ شى خوړلے کۀ هغه د اِمام کره مېلمه وى يا يې مزدور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3259, 'Leviticus 22:11', 'Leviticus', 22, 11, '&nbsp;خو د اِمام غلامان، چې هغه يې په پېسو اخستى وى يا يې په خپل کور کښې پېدا شوى وى، نو هغوئ هغه خوراک خوړلے شى کوم چې اِمام ته ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3260, 'Leviticus 22:12', 'Leviticus', 22, 12, '&nbsp;کۀ د اِمام لور د يو داسې سړى سره وادۀ وکړى چې هغه اِمام نۀ وى نو هغه ښځه به دا مقدسې نذرانې نۀ شى خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3261, 'Leviticus 22:13', 'Leviticus', 22, 13, '&nbsp;خو کۀ د هغۀ لور کونډه يا طلاقه شوې وى چې د هغې بچى نۀ وى او هغه واپس راغلې وى او د پلار په کور کښې اوسيږى نو هغه دا خوراک خوړلے شى چې کوم يې پلار ته د اِمام په توګه مِلاو شوے وى. صِرف د اِمامانو د خاندان کس دا خوراک خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3262, 'Leviticus 22:14', 'Leviticus', 22, 14, '&nbsp;کۀ يو کس د اِمامانو د خاندان نه نۀ وى او د مقدسې نذرانې نه څۀ په غلطۍ سره وخورى، نو هغه به خامخا اِمام ته د دې پوره قيمت او شل فيصده تاوان هم ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3263, 'Leviticus 22:15', 'Leviticus', 22, 15, '&nbsp;اِمامان به د دې نذرانو سپکاوے نۀ کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3264, 'Leviticus 22:16', 'Leviticus', 22, 16, '&nbsp;چا ته چې د مقدسو نذرانو د خوړلو اجازت نۀ وى نو هغه خلق به ورته نۀ شى پرېښودلے، کۀ داسې وشى نو د دې په وجه به هغه کس ګناهګار شى او سزا به ورته مِلاو شى. زۀ مالِک خُدائ يم او زۀ نذرانې مقدسې کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3265, 'Leviticus 22:17', 'Leviticus', 22, 17, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3266, 'Leviticus 22:18', 'Leviticus', 22, 18, '&nbsp;”هارون او د هغۀ زامنو ته او ټولو اِسرائيلو ته دا اصُول وښايه. کله چې يو اِسرائيلے يا په بنى اِسرائيلو کښې اوسېدونکے مسافر يوه سوزېدونکې نذرانه پېش کوى، کۀ هغه يوه منښته يا رضاکارانه نذرانه وى، نو په هغه ځناور کښې دې هيڅ عېب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3267, 'Leviticus 22:19', 'Leviticus', 22, 19, '&nbsp;دا ځناور به خامخا نر وى، ګډ يا چېلے چې هيڅ عېب په کښې نۀ وى د دې دپاره چې دا نذرانه ستاسو نه قبوله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3268, 'Leviticus 22:20', 'Leviticus', 22, 20, '&nbsp;کۀ تاسو يو داسې ځناور پېش کوئ چې څۀ عېب په کښې وى، نو مالِک خُدائ به دا نۀ قبلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3269, 'Leviticus 22:21', 'Leviticus', 22, 21, '&nbsp;کله چې څوک مالِک خُدائ ته د سلامتۍ نذرانه پېش کوى، کۀ هغه يوه منښته يا رضاکارانه نذرانه وى، نو په هغه ځناور کښې به څۀ عېب نۀ وى، دا د دې دپاره چې قبوله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3270, 'Leviticus 22:22', 'Leviticus', 22, 22, '&nbsp;مالِک خُدائ ته داسې ځناور مۀ پېش کوئ چې ړوند، ګوډ، يا ناسور شوے زخم په کښې وى، يا يې په څرمن کښې پمنوالے يا خارښت وى. داسې ځناور په قربان‌ګاه باندې په اور تيارېدونکې نذرانې په توګه مۀ پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3271, 'Leviticus 22:23', 'Leviticus', 22, 23, '&nbsp;د رضاکارانه نذرانې په توګه تاسو داسې ځناور پېش کولے شئ چې هغه لنډ وى يا کۀ هغه صحيح شکل نۀ لرى، خو دا به په منښته کښې قبلېدونکے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3272, 'Leviticus 22:24', 'Leviticus', 22, 24, '&nbsp;مالِک خُدائ ته داسې ځناور مۀ پېش کوئ چې په ټکولو، پرې کولو، زخمى کولو يا ويستلو په وجه خصى شوے وى. ستاسو په مُلک کښې به د دې قِسم نذرانو اجازت نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3273, 'Leviticus 22:25', 'Leviticus', 22, 25, '&nbsp;په اور تيارېدونکې نذرانې په توګه داسې ځناور مۀ پېش کوئ چې د يو پردى سړى نه اخستے شوے وى. داسې ځناور عېبژن ګڼلے شى او قبلېدونکى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3274, 'Leviticus 22:28', 'Leviticus', 22, 28, '&nbsp;يوه غوا او د هغې سخے يا ګډه او د هغې ګډُورے يا يوه چېلۍ او د هغې بچے په يوه ورځ مۀ حلالوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3275, 'Leviticus 22:29', 'Leviticus', 22, 29, '&nbsp;کله چې تاسو مالِک خُدائ ته د شکرانې قربانى پېش کوئ، نو په هغه اصُولو عمل کوئ نو داسې به تاسو قبول شئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3276, 'Leviticus 22:30', 'Leviticus', 22, 30, '&nbsp;هم په هغه ورځ باندې دا وخورئ او د دې هيڅ هم بلې ورځې ته مۀ پرېږدئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3277, 'Leviticus 22:31', 'Leviticus', 22, 31, '&nbsp;مالِک خُدائ وفرمائيل، ”زما حُکمونه منئ، زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3278, 'Leviticus 22:32', 'Leviticus', 22, 32, '&nbsp;زما د مقدس نوم سپکاوے مۀ کوئ، ټول اِسرائيليان دې دا اِقرار وکړى چې زۀ مقدس يم. زۀ مالِک خُدائ يم او زۀ تاسو مقدس کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3279, 'Leviticus 22:33', 'Leviticus', 22, 33, '&nbsp;او ما تاسو د مِصر مُلک نه راوويستلئ چې ستاسو خُدائ پاک شم. زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3280, 'Leviticus 23:1', 'Leviticus', 23, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3281, 'Leviticus 23:2', 'Leviticus', 23, 2, '&nbsp;”بنى اِسرائيلو ته د مذهبى اخترونو دپاره دا اصُول وښايه چې په دې کښې هغوئ د عبادت دپاره راغونډ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3282, 'Leviticus 23:3', 'Leviticus', 23, 3, '&nbsp;ستاسو سره شپږ ورځې شته چې خپل کار په کښې کولے شئ، خو ياد ساتئ اوومه ورځ د سبت ورځ ده، چې د آرام دپاره ده. په دې ورځ کار مۀ کوئ او د عبادت دپاره راغونډېږئ. د سبت ورځ د مالِک خُدائ ده، چې تاسو چرته هم اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3283, 'Leviticus 23:4', 'Leviticus', 23, 4, '&nbsp;د دې اخترونو اِعلان په مقرر شوو وختونو باندې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3284, 'Leviticus 23:5', 'Leviticus', 23, 5, '&nbsp;د فسحې اختر، د د اولنۍ مياشتې د څوارلسمې ورځې د نمرپرېواتو نه شروع کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3285, 'Leviticus 23:6', 'Leviticus', 23, 6, '&nbsp;په پينځلسمه ورځ د پتيرې روټۍ اختر شروع کيږى او اووۀ ورځې به تاسو خمبيره روټۍ نۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3286, 'Leviticus 23:7', 'Leviticus', 23, 7, '&nbsp;د دې ورځو په اوله ورځ به تاسو د عبادت دپاره راغونډېږئ او هغه يو کار هم مۀ کوئ چې تاسو يې هره ورځ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3287, 'Leviticus 23:8', 'Leviticus', 23, 8, '&nbsp;اووۀ ورځې مالِک خُدائ ته په اور تيارېدونکې نذرانې پېش کړئ. په اوومه ورځ به تاسو بيا د عبادت دپاره راغونډ شئ، خو هغه يو کار به هم نۀ کوئ کوم چې تاسو هره ورځ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3288, 'Leviticus 23:11', 'Leviticus', 23, 11, '&nbsp;هغه به دا مالِک خُدائ ته د يوې خاص نذرانې په توګه پېش کړى، تر څو چې تاسو قبول شئ. اِمام به دا د سبت پسې په بله ورځ پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3289, 'Leviticus 23:12', 'Leviticus', 23, 12, '&nbsp;په کومه ورځ چې تاسو د فصل نذرانه پېش کوئ، نو د يو کال ګډُورے هم د سوزېدونکې نذرانې په توګه قربانى کړئ چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3290, 'Leviticus 23:13', 'Leviticus', 23, 13, '&nbsp;تاسو د دې سره دوه کلو ښۀ اوړۀ چې د زيتُونو تېل ورسره ګډ وى په اور تيارېدونکې نذرانې په توګه پېش کړئ. د دې نذرانې خوشبوئى په مالِک خُدائ باندې ښۀ لګى. تاسو د دې سره يو ليټر د ميو نذرانه هم پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3291, 'Leviticus 23:14', 'Leviticus', 23, 14, '&nbsp;ترڅو پورې چې تاسو دا نذرانه خُدائ پاک ته نۀ وى راوړې نو تر هغې د نوې غلې روټۍ، وريتې شوې يا کچه دانې مۀ خورئ. په راتلونکى ټولو وختونو کښې ستاسو ټول اولاد به دا اصُول منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3292, 'Leviticus 23:15', 'Leviticus', 23, 15, '&nbsp;سبت پسې ورځې نه پوره اووۀ هفتې وشمېرئ يعنې د هغه ورځ نه په کومه ورځ چې تاسو د خپل فصل ګېډے مالِک خُدائ ته د پېش کېدو دپاره راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3293, 'Leviticus 23:16', 'Leviticus', 23, 16, '&nbsp;د اوؤم سبت د ورځې نه پس، په پنځوسمه ورځ، مالِک خُدائ ته د نوى فصل يوه بله نذرانه پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3294, 'Leviticus 23:17', 'Leviticus', 23, 17, '&nbsp;هر يو خاندان دې دوه دوه روټۍ راوړى او دا دې مالِک خُدائ ته د خاص تُحفې په توګه پېش کړى. هره يوه روټۍ دې خمبيره شوې د دوه کلو ښو اوړو نه پخه شوې وى او دا به مالِک خُدائ ته د وړومبى رېبلے شوى فصل د نذرانې په توګه پېش کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3295, 'Leviticus 23:18', 'Leviticus', 23, 18, '&nbsp;او قوم دې د دې روټۍ سره اووۀ يو کلن ګډُورى، يو غوَيے او دوه ګډان پېش کړى، چې هيڅ عېب په کښې نۀ وى. دا به د سوزېدونکې نذرانې په توګه، سره د غلې د نذرانې او د ميو د نذرانې سره مالِک خُدائ ته پېش کيږى. د دې نذرانې خوشبوئى په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3296, 'Leviticus 23:19', 'Leviticus', 23, 19, '&nbsp;يو چېلے د ګناه د نذرانې په توګه او دوه يو کلن ګډُورى د سلامتۍ د نذرانې په توګه هم پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3297, 'Leviticus 23:20', 'Leviticus', 23, 20, '&nbsp;اِمام به روټۍ د دوو ګډورو سره د اِمامانو دپاره د خاص تُحفې په توګه هم پېش کړى. دا نذرانې مقدسې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3298, 'Leviticus 23:21', 'Leviticus', 23, 21, '&nbsp;په هغه ورځ هغه يو کار هم مۀ کوئ چې تاسو يې هره ورځ کوئ او د عبادت دپاره راغونډېږئ. ستاسو اولاد چې چرته هم اوسيږى دا اصُول دې په راتلونکى ټولو وختونو کښې منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3299, 'Leviticus 23:22', 'Leviticus', 23, 22, '&nbsp;کله چې تاسو د خپلو پټو فصل رېبئ، نو فصل د پټو تر غاړو پورې مۀ رېبئ او چې کوم وَږى پاتې شى نو د هغې رېبلو له واپس مۀ ورځئ، دا د غريبانانو خلقو او مسافرو دپاره پرېږدئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3300, 'Leviticus 23:25', 'Leviticus', 23, 25, '&nbsp;مالِک خُدائ ته يوه په اور تيارېدونکې نذرانه پېش کړئ او هغه يو کار هم مۀ کوئ چې تاسو يې هره ورځ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');